const dictionaries = { en, ar };
const I18n = createContext<{ lang: Lang; t: (key: string) => string; setLang: (lang: Lang) => void }>({ lang:'ar', t:key=>key, setLang:()=>{} });

export function I18nProvider({ initialLang, children }: { initialLang: Lang; children: React.ReactNode }) {
  const [lang, setState] = useState<Lang>(initialLang);
  const setLang = (next: Lang) => {
    const cookieSecurity = location.protocol === 'https:' ? ';samesite=none;secure;partitioned' : ';samesite=lax';
    document.cookie = `ff_lang=${next};path=/;max-age=31536000${cookieSecurity}`;
    document.documentElement.lang = next;
    document.documentElement.dir = next === 'ar' ? 'rtl' : 'ltr';
    setState(next);
  };
  return <I18n.Provider value={{ lang, t:(key)=>dictionaries[lang][key] || en[key] || key, setLang }}>{children}</I18n.Provider>;
}
export const useI18n = () => useContext(I18n);
